"""Multi-sample inference module for structured IE with vLLM + XGrammar constrained decoding.

Provides VLLMSampler for batch sampling, prompt construction for UIE tasks,
and a full pipeline that produces SampledInstance dicts.
"""

from __future__ import annotations

import json
import os
from typing import Any


# ---------------------------------------------------------------------------
# UIE JSON schema for XGrammar constrained decoding
# ---------------------------------------------------------------------------

UIE_JSON_SCHEMA: dict[str, Any] = {
    "type": "object",
    "properties": {
        "entities": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "text": {"type": "string"},
                    "type": {"type": "string"},
                    "start": {"type": "integer"},
                    "end": {"type": "integer"},
                },
                "required": ["text", "type", "start", "end"],
            },
        },
        "relations": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "head": {"type": "string"},
                    "tail": {"type": "string"},
                    "type": {"type": "string"},
                    "head_start": {"type": "integer"},
                    "head_end": {"type": "integer"},
                    "tail_start": {"type": "integer"},
                    "tail_end": {"type": "integer"},
                },
                "required": ["head", "tail", "type", "head_start", "head_end",
                             "tail_start", "tail_end"],
            },
        },
        "events": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "trigger": {
                        "type": "object",
                        "properties": {
                            "text": {"type": "string"},
                            "type": {"type": "string"},
                            "start": {"type": "integer"},
                            "end": {"type": "integer"},
                        },
                        "required": ["text", "type", "start", "end"],
                    },
                    "arguments": {
                        "type": "array",
                        "items": {
                            "type": "object",
                            "properties": {
                                "text": {"type": "string"},
                                "role": {"type": "string"},
                                "start": {"type": "integer"},
                                "end": {"type": "integer"},
                            },
                            "required": ["text", "role", "start", "end"],
                        },
                    },
                },
                "required": ["trigger", "arguments"],
            },
        },
    },
    "required": ["entities", "relations", "events"],
}

_EMPTY_EXTRACTION: dict[str, list] = {"entities": [], "relations": [], "events": []}


# ---------------------------------------------------------------------------
# VLLMSampler
# ---------------------------------------------------------------------------

class VLLMSampler:
    """Batch sampler backed by vLLM with optional XGrammar JSON constrained decoding."""

    def __init__(
        self,
        model_path: str,
        tensor_parallel_size: int = 1,
        max_model_len: int = 4096,
        gpu_memory_utilization: float = 0.90,
    ):
        """Initialise the vLLM engine.

        Args:
            model_path: Path to the HuggingFace model (local or hub id).
            tensor_parallel_size: Number of GPUs for tensor parallelism.
            max_model_len: Maximum sequence length.
            gpu_memory_utilization: Fraction of GPU memory to reserve.
        """
        from vllm import LLM

        self.llm = LLM(
            model=model_path,
            tensor_parallel_size=tensor_parallel_size,
            max_model_len=max_model_len,
            gpu_memory_utilization=gpu_memory_utilization,
        )
        self._model_path = model_path

# Data

Data can be downloaded from [Google Drive](https://drive.google.com/drive/folders/1c5-0YwnoJx8NS6CV2f-NoTHR__BdkNqw?usp=sharing).

Relation information file has been uploaded.


```
Data Format:
{
  'title',
  'sents':     [
                  [word in sent 0],
                  [word in sent 1]
               ]
  'vertexSet': [
                  [
                    { 'name': mention_name, 
                      'sent_id': mention in which sentence, 
                      'pos': postion of mention in a sentence, 
                      'type': NER_type}
                    {anthor mention}
                  ], 
                  [anthoer entity]
                ]
  'labels':   [
                {
                  'h': idx of head entity in vertexSet,
                  't': idx of tail entity in vertexSet,
                  'r': relation,
                  'evidence': evidence sentences' id
                }
              ]
}
```

Please submit the test set result to Codalab.
